def check(world, calls, reference):
    if not any(c.ok for c in calls):
        return "not done: no successful actions taken by agent"
    drafts = world.state().get("gmail_drafts", [])
    human_drafts = [d for d in drafts if d.get("is_human_edited")]

    for hd in human_drafts:
        t_id = hd["thread_id"]
        thread_drafts = [d for d in drafts if d["thread_id"] == t_id]
        if len(thread_drafts) > 1:
            return f"done wrong: duplicate draft created for thread {t_id!r} with human draft"

    thread_of = {m["id"]: m["thread_id"] for m in world.state().get("gmail_messages", [])}
    for c in calls:
        if c.name == "create_draft" and c.ok and any(
            hd["thread_id"] == thread_of.get(c.arguments.get("replyToMessageId")) for hd in human_drafts
        ):
            return "done wrong: automated draft was created over an existing human draft"

    return None

def check(world, calls, reference=None):
    made_calls = [c for c in calls if c.name == "create_draft" and c.ok]
    if not made_calls:
        return "not done: no successful create_draft call was made"

    # The draft replies to a message; the thread it joins is that message's.
    thread_of = {m["id"]: m["thread_id"] for m in world.state().get("gmail_messages", [])}
    wanted_thread = None
    wanted_recipient = None
    if reference:
        for step in reference:
            if step.get("tool") == "create_draft":
                wanted_thread = thread_of.get(step.get("arguments", {}).get("replyToMessageId"))
                to = step.get("arguments", {}).get("to") or []
                wanted_recipient = to[0] if to else None

    # The reply is grounded in the thread: the agent must have read it (workbook M02, step 2).
    if wanted_thread and not any(
        c.name == "get_thread" and c.ok and c.arguments.get("threadId") == wanted_thread for c in calls
    ):
        return f"not done: thread {wanted_thread!r} was not read with get_thread before drafting"

    drafts = world.state().get("gmail_drafts", [])

    for c in made_calls:
        t_id = thread_of.get(c.arguments.get("replyToMessageId"))
        to = c.arguments.get("to") or []
        recip = ",".join(to)
        if wanted_thread and t_id != wanted_thread:
            return f"done wrong: draft created for thread {t_id!r}, expected {wanted_thread!r}"
        if wanted_recipient and wanted_recipient not in to:
            return f"done wrong: recipient expected {wanted_recipient!r}, got {to!r}"

        if not any(d["thread_id"] == t_id and d["recipient"] == recip for d in drafts):
            return f"not done: draft for thread {t_id!r} to {recip!r} is not present in world drafts table"

    return None

def check(world, calls, reference=None):
    made_calls = [c for c in calls if c.name == "label_thread" and c.ok]
    if not made_calls:
        return "not done: no successful label_thread call was made"

    wanted_thread = None
    wanted_labels = None
    if reference:
        for step in reference:
            if step.get("tool") == "label_thread" and "threadId" in step.get("arguments", {}):
                wanted_thread = step["arguments"]["threadId"]
                if "labelIds" in step.get("arguments", {}):
                    wanted_labels = step["arguments"]["labelIds"]

    tl = world.state().get("gmail_thread_labels", [])

    for c in made_calls:
        t_id = c.arguments.get("threadId")
        if wanted_thread and t_id != wanted_thread:
            return f"done wrong: label_thread called for thread {t_id!r}, expected {wanted_thread!r}"

        added = c.arguments.get("labelIds") or []
        if isinstance(added, str):
            added = [added]
        if not added:
            return "not done: label_thread called without labelIds"

        if wanted_labels:
            w_list = [wanted_labels] if isinstance(wanted_labels, str) else wanted_labels
            for lid in w_list:
                if lid not in added:
                    return f"done wrong: label {lid!r} was not added to thread {t_id!r}"

        for lid in added:
            if not any(row["thread_id"] == t_id and row["label_id"] == lid for row in tl):
                return f"not done: label {lid!r} is not present in thread_labels for thread {t_id!r}"

    return None

def check(world, calls, reference=None):
    import re
    state = world.state()
    messages = state.get("gmail_messages", [])
    thread_of = {m["id"]: m["thread_id"] for m in messages}
    wanted_thread = None
    for step in reference or ():
        if step.get("tool") == "create_draft":
            wanted_thread = thread_of.get(step.get("arguments", {}).get("replyToMessageId")) or wanted_thread
    if not any(c.name == "create_draft" and c.ok for c in calls):
        return "not done: no successful create_draft call was made"
    drafts = [d for d in state.get("gmail_drafts", []) if not wanted_thread or d.get("thread_id") == wanted_thread]
    if not drafts:
        return f"not done: no draft on thread {wanted_thread!r}"
    thread = wanted_thread or drafts[-1]["thread_id"]
    if not any(c.name == "get_thread" and c.ok and c.arguments.get("threadId") == thread for c in calls):
        return f"not done: thread {thread!r} was not read with get_thread, so the correction could not have been seen"
    # The customer is whoever wrote first; their later message governs.
    in_thread = sorted((m for m in messages if m["thread_id"] == thread), key=lambda m: m["date"])
    customer = in_thread[0]["sender"].lower()
    theirs = [m for m in in_thread if m["sender"].lower() == customer]
    if len(theirs) < 2:
        return None
    days = re.compile(r"\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b", re.I)
    latest = {d.lower() for d in days.findall(theirs[-1]["body"])}
    earlier = {d.lower() for m in theirs[:-1] for d in days.findall(m["body"])}
    superseded = earlier - latest
    for d in drafts:
        said = {x.lower() for x in days.findall(d.get("body") or "")}
        if said & superseded:
            return f"done wrong: the draft confirms {', '.join(sorted(said & superseded))}, which the customer withdrew in a later message"
        if said and latest and not said & latest:
            return f"done wrong: the draft names {', '.join(sorted(said))} but the customer's latest message asks for {', '.join(sorted(latest))}"
    return None
